result = shops.CALCULATE(
    shop_name=shop_name, # Get the name of the shop
    total_quantity=SUM(stocks.quantity) # Calculate the total quantity for each shop by summing quantities in its 'stocks' sub-collection
).TOP_K(
    1, # Get only the top 1 shop
    by=total_quantity.DESC() # Order by total_quantity in descending order to find the greatest
).CALCULATE(
    shop_name=shop_name # Select only the shop_name as the final output
)

bike_most_traveled_in_zip = trips.WHERE(
    zip_code == 94002
).PARTITION(
    name="bike_trips_group",
    by=bike_id
).CALCULATE(
    bike_id = bike_id,
    num_trips = COUNT(trips)
).TOP_K(1, by=num_trips.DESC()).CALCULATE(bike_id=bike_id)
